import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Ensure output directory exists
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)){
    fs.mkdirSync(outputDir, { recursive: true });
}

// Z-up conversion matrix: Rotate -90 degrees around X
const zUpMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);

function bakeAndFlatten(object, outputGroup) {
    // Ensure world matrices are up to date
    object.updateMatrixWorld(true);

    object.traverse((child) => {
        // Handle InstancedMesh first as it also inherits from Mesh
        if (child.isInstancedMesh) {
            const count = child.count;
            const instanceMatrix = new THREE.Matrix4();

            for (let i = 0; i < count; i++) {
                child.getMatrixAt(i, instanceMatrix);

                // Calculate full transform: Z_UP_ROTATION * OBJECT_WORLD_TRANSFORM * INSTANCE_LOCAL_TRANSFORM
                const transform = new THREE.Matrix4()
                    .copy(zUpMatrix)
                    .multiply(child.matrixWorld)
                    .multiply(instanceMatrix);

                // Clone geometry and bake transform
                const geom = child.geometry.clone();
                geom.applyMatrix4(transform);

                const mesh = new THREE.Mesh(geom);
                mesh.name = `${child.name}_${i}`;
                outputGroup.add(mesh);
            }
        } else if (child.isMesh) {
            // Calculate full transform: Z_UP_ROTATION * OBJECT_WORLD_TRANSFORM
            const transform = new THREE.Matrix4()
                .copy(zUpMatrix)
                .multiply(child.matrixWorld);

            // Clone geometry and bake transform
            const geom = child.geometry.clone();
            geom.applyMatrix4(transform);

            const mesh = new THREE.Mesh(geom);
            mesh.name = child.name;
            outputGroup.add(mesh);
        }
    });
}

// 1. Create the scene from the provided file
const scene = createScene();

// 2. Container for the flattened, transformed meshes
const exportScene = new THREE.Group();

// 3. Process the scene
bakeAndFlatten(scene, exportScene);

// 4. Export to OBJ
const exporter = new OBJExporter();
const result = exporter.parse(exportScene);

// 5. Write to file
const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, result);

console.log(`Successfully exported to ${outputPath}`);

